import React, { useState, useEffect } from "react";
import {
  collection,
  getDocs,
  doc,
  setDoc,
  deleteDoc,
} from "firebase/firestore";
import { db } from "../firebase/Firebase";
import { useNavigate } from "react-router-dom";
import css from "../styles/AddTechnology.module.css";
const AddTechnology = () => {
  const [techName, setTechName] = useState("");
  const [category, setCategory] = useState("");
  const [technologies, setTechnologies] = useState([]);
  const [editId, setEditId] = useState(null);
  const [editName, setEditName] = useState("");
  const [editCategory, setEditCategory] = useState("");
  const navigate = useNavigate();

  const fetchTechnologies = async () => {
    const querySnapshot = await getDocs(collection(db, "Technologies"));
    const data = querySnapshot.docs.map((doc) => ({
      id: doc.id,
      ...doc.data(),
    }));
    setTechnologies(data);
  };

  useEffect(() => {
    fetchTechnologies();
  }, []);

  const handleAdd = async () => {
    if (!techName || !category) return alert("Fill all fields!");
    await setDoc(doc(db, "Technologies", techName), {
      name: techName,
      category: category,
    });
    alert("Technology added!");
    setTechName("");
    setCategory("");
    fetchTechnologies();
  };

  const handleEdit = (tech) => {
    setEditId(tech.id);
    setEditName(tech.name);
    setEditCategory(tech.category);
  };

  const handleUpdate = async () => {
    await setDoc(doc(db, "Technologies", editId), {
      name: editName,
      category: editCategory,
    });
    alert("Technology updated!");
    setEditId(null);
    fetchTechnologies();
  };

  const handleDelete = async (id) => {
    if (window.confirm("Are you sure you want to delete this technology?")) {
      await deleteDoc(doc(db, "Technologies", id));
      alert("Technology deleted!");
      fetchTechnologies();
    }
  };

  return (
    <div className={css.container}>
      <h2>Add Technology</h2>
      <div className={css.inputlist}>
        <input
          placeholder="Technology Name"
          value={techName}
          onChange={(e) => setTechName(e.target.value)}
        />
        <input
          placeholder="Category"
          value={category}
          onChange={(e) => setCategory(e.target.value)}
        />
        <button onClick={handleAdd}>Add</button>
      </div>

      <h2>Existing Technologies</h2>
      <div className={css.listofq}>
        <ul>
          {technologies.map((tech) => (
            <li key={tech.id}>
              {editId === tech.id ? (
                <div className={css.liinput}>
                  <input
                    type="text"
                    value={editName}
                    onChange={(e) => setEditName(e.target.value)}
                  />
                  <input
                    type="text"
                    value={editCategory}
                    onChange={(e) => setEditCategory(e.target.value)}
                  />
                  <button onClick={handleUpdate}>Save</button>
                  <button onClick={() => setEditId(null)}>Cancel</button>
                </div>
              ) : (
                <div className={css.nonlist}>
                  <span>
                    {tech.name} ({tech.category})
                  </span>
                  <button onClick={() => handleEdit(tech)}>Edit</button>
                  <button
                    onClick={() => handleDelete(tech.id)}
                    style={{ marginLeft: "10px", color: "red" }}
                  >
                    Delete
                  </button>
                  <button
                    onClick={() => navigate(`/questions/${tech.id}`)}
                    style={{ marginLeft: "10px" }}
                  >
                    View Questions
                  </button>
                </div>
              )}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export default AddTechnology;
