import React, { useState, useEffect } from "react";
import {
  collection,
  getDocs,
  addDoc,
  doc,
  deleteDoc,
  setDoc,
} from "firebase/firestore";
import { db } from "../firebase/Firebase";
import { useParams } from "react-router-dom";
import css from "../styles/AddQuestion.module.css";

const AddQuestion = () => {
  const { techName } = useParams(); // get technology name from URL
  const [question, setQuestion] = useState("");
  const [answer, setAnswer] = useState("");
  const [code, setCode] = useState("");
  const [questions, setQuestions] = useState([]);
  const [editId, setEditId] = useState(null);
  const [editQuestion, setEditQuestion] = useState("");
  const [editAnswer, setEditAnswer] = useState("");
  const [editCode, setEditCode] = useState("");

  const fetchQuestions = async () => {
    const querySnapshot = await getDocs(
      collection(db, "Technologies", techName, "Questions")
    );
    const data = querySnapshot.docs.map((doc) => ({
      id: doc.id,
      ...doc.data(),
    }));
    setQuestions(data);
  };

  useEffect(() => {
    fetchQuestions();
  }, [techName]);

  const handleAdd = async () => {
    if (!question || !answer) return alert("Fill all fields!");
    await addDoc(collection(db, "Technologies", techName, "Questions"), {
      ques1: question,
      ansQue1: answer,
      code: code,
    });
    alert("Question added!");
    setQuestion("");
    setAnswer("");
    setCode("");
    fetchQuestions();
  };

  const handleEdit = (q) => {
    setEditId(q.id);
    setEditQuestion(q.ques1);
    setEditAnswer(q.ansQue1);
    setEditCode(q.code || "");
  };

  const handleUpdate = async () => {
    await setDoc(doc(db, "Technologies", techName, "Questions", editId), {
      ques1: editQuestion,
      ansQue1: editAnswer,
      code: editCode,
    });
    alert("Question updated!");
    setEditId(null);
    fetchQuestions();
  };

  const handleDelete = async (id) => {
    if (window.confirm("Are you sure you want to delete this question?")) {
      await deleteDoc(doc(db, "Technologies", techName, "Questions", id));
      alert("Question deleted!");
      fetchQuestions();
    }
  };

  return (
    <div className={css.container}>
      <h2>Questions for {techName}</h2>
      <div className={css.inputlist}>
        <input
          placeholder="Question"
          value={question}
          onChange={(e) => setQuestion(e.target.value)}
        />
        <input
          placeholder="Answer"
          value={answer}
          onChange={(e) => setAnswer(e.target.value)}
        />
        <input
          placeholder="Code Example"
          value={code}
          onChange={(e) => setCode(e.target.value)}
        />
        <button onClick={handleAdd}>Add</button>
      </div>

      <div className={css.listofq}>
        <ul>
          {questions.map((q) => (
            <li key={q.id}>
              {editId === q.id ? (
                <div className={css.liinput}>
                  <input
                    type="text"
                    value={editQuestion}
                    onChange={(e) => setEditQuestion(e.target.value)}
                  />
                  <input
                    type="text"
                    value={editAnswer}
                    onChange={(e) => setEditAnswer(e.target.value)}
                  />
                  <input
                    type="text"
                    value={editCode}
                    onChange={(e) => setEditCode(e.target.value)}
                  />
                  <button onClick={handleUpdate}>Save</button>
                  <button onClick={() => setEditId(null)}>Cancel</button>
                </div>
              ) : (
                <div className={css.nonlist}>
                  <span>
                    <strong>{q.ques1}</strong> — {q.ansQue1}
                  </span>
                  {q.code && <pre>{q.code}</pre>}
                  <button onClick={() => handleEdit(q)}>Edit</button>
                  <button className={css.danger}
                    onClick={() => handleDelete(q.id)}
                   
                  >
                    Delete
                  </button>
                </div>
              )}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export default AddQuestion;
